#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

const int MAXN = 12;
const int INF = 1000000009;
const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

int N, T;
char gridA[MAXN][MAXN], gridB[MAXN][MAXN];
int dist[MAXN][MAXN];
bool visited[MAXN][MAXN];

struct Point {
    int x, y;
    Point() {}
    Point(int x, int y) : x(x), y(y) {}
};

void bfs(int sx, int sy) {
    for (int i = 0; i < N; ++i)
        fill(dist[i], dist[i] + N, INF);
    fill(&visited[0][0], &visited[N][0], false);
    queue<Point> q;
    visited[sx][sy] = true;
    dist[sx][sy] = 0;
    q.push(Point(sx, sy));
    while (!q.empty()) {
        Point cur = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = cur.x + dx[i], ny = cur.y + dy[i];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny] && isdigit(gridA[nx][ny])) {
                visited[nx][ny] = true;
                dist[nx][ny] = dist[cur.x][cur.y] + 1;
                q.push(Point(nx, ny));
            }
        }
    }
}

bool dp[72][12][12][12][12];
bool reachable[12][12][12][12];

int capacity[290][290];
int parent[290];
bool vis[290];

bool bfsFlow() {
    fill(vis, vis + 290, false);
    fill(parent, parent + 290, 0);
    queue<int> q;
    vis[0] = true;
    q.push(0);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (u == 2 * N * N + 1) return true;
        for (int v = 0; v <= 2 * N * N + 1; ++v) {
            if (capacity[u][v] && !vis[v]) {
                vis[v] = true;
                parent[v] = u;
                q.push(v);
            }
        }
    }
    return false;
}

void solve() {
    cin >> N >> T;
    for (int i = 0; i < N; ++i) cin >> gridA[i];
    for (int i = 0; i < N; ++i) cin >> gridB[i];
    int sx, sy;
    cin >> sx >> sy;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (gridA[i][j] == 'Z') {
                sx = i; sy = j;
            }
        }
    }
    bfs(sx, sy);
    memset(dp, 0, sizeof(dp));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(gridA[i][j])) {
                dp[0][i][j][i][j] = true;
            }
        }
    }
    for (int t = 0; t < T; ++t) {
        for (int px = 0; px < N; ++px) {
            for (int py = 0; py < N; ++py) {
                for (int x = 0; x < N; ++x) {
                    for (int y = 0; y < N; ++y) {
                        if (!dp[t][px][py][x][y]) continue;
                        if (dist[x][y] <= t) continue;
                        for (int d = 0; d < 4; ++d) {
                            int nx = x + dx[d], ny = y + dy[d];
                            if (nx >= 0 && nx < N && ny >= 0 && ny < N && isdigit(gridA[nx][ny]) && dist[nx][ny] >= t + 1) {
                                dp[t + 1][px][py][nx][ny] = true;
                            }
                        }
                    }
                }
            }
        }
    }
    memset(reachable, 0, sizeof(reachable));
    for (int t = 0; t <= T; ++t) {
        for (int px = 0; px < N; ++px) {
            for (int py = 0; py < N; ++py) {
                for (int x = 0; x < N; ++x) {
                    for (int y = 0; y < N; ++y) {
                        if (dp[t][px][py][x][y]) {
                            reachable[px][py][x][y] = true;
                        }
                    }
                }
            }
        }
    }
    memset(capacity, 0, sizeof(capacity));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(gridA[i][j])) {
                capacity[0][i * N + j + 1] = gridA[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(gridB[i][j])) {
                capacity[N * N + i * N + j + 1][2 * N * N + 1] = gridB[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!isdigit(gridA[i][j])) continue;
            for (int k = 0; k < N; ++k) {
                for (int l = 0; l < N; ++l) {
                    if (!isdigit(gridA[k][l])) continue;
                    if (!reachable[i][j][k][l]) continue;
                    capacity[i * N + j + 1][N * N + k * N + l + 1] = INF;
                }
            }
        }
    }
    while (bfsFlow()) {
        int flow = INF;
        for (int u = 2 * N * N + 1; u; u = parent[u]) {
            flow = min(flow, capacity[parent[u]][u]);
        }
        for (int u = 2 * N * N + 1; u; u = parent[u]) {
            capacity[parent[u]][u] -= flow;
            capacity[u][parent[u]] += flow;
        }
    }
    int result = 0;
    for (int i = 0; i <= 2 * N * N + 1; ++i) {
        result += capacity[i][0];
    }
    cout << result << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve();
    return 0;
}
